          tr: "Kullanımınıza bağlı olarak. Polar genellikle koşu ve bisikletçilikte güçlü, gelişmiş kalp-farkedici analizleri (HR zonaları, laktat sınırı) sunar. Garmin dış sporlar için daha kapsamlı ve geniş bir ekosistem sunar. Her iki ürün de FitMesh ile Health Connect aracılığıyla entegre olup, her ikinci markanın cihazına sahipseniz paralel olarak kullanabilirsiniz.",
          nl: "Dat hangt af van je belangrijkste gebruik. Polar is van oudsher sterk in hardlopen en fietsen met geavanceerde cardio-analyse (HR-zones, lactaatdrempel). Garmin is completer voor outdoorsporten met een breder ecosysteem. Beide integreren met FitMesh via Health Connect, dus je kunt ze parallel gebruiken als je apparaten van beide merken hebt.",
          ja: "主な用途によります。Polar は伝統的にランニングとサイクリングに強く、高度な心拍分析 (心拍ゾーン、乳酸閾値) を備えています。Garmin はアウトドアスポーツ向けにより充実しており、エコシステムも広いです。どちらも Health Connect 経由で FitMesh と連携するため、両ブランドのデバイスを持っていれば並行して使えます。",
          ko: "주된 용도에 따라 다릅니다. Polar 는 전통적으로 러닝과 사이클링에 강하며 고급 심박 분석 (심박 존, 젖산 역치) 을 제공합니다. Garmin 은 아웃도어 스포츠에 더 완성도가 높고 생태계가 더 넓습니다. 둘 다 Health Connect 를 통해 FitMesh 와 연동되므로, 두 브랜드의 기기를 모두 가지고 있다면 병행해서 사용할 수 있습니다.",
