          pt: "Posso usar o FitMesh em dois celulares ao mesmo tempo?",
          fr: "Puis-je utiliser FitMesh sur deux téléphones en même temps?",
          pl: "Czy mogę używać FitMesh na dwóch telefonach jednocześnie?",
