          nl: "FitMesh ondersteunt de meest voorkomende Colmi-modellen die het standaard Bluetooth-protocol gebruiken, waaronder R-serie modellen (R02, R06, R08, R09, R10) en andere met vergelijkbare functies. De compatibiliteit wordt geleidelijk uitgebreid. Staat jouw model er niet bij, doe dan mee aan de beta en laat het ons weten: gevraagde modellen krijgen prioriteit.",
          ja: "FitMesh は、標準 Bluetooth プロトコルを使用する最も一般的な Colmi モデル（R シリーズの R02、R06、R08、R09、R10 や、類似の機能を持つその他のモデルを含む）に対応しています。互換性は段階的に拡大されています。お使いのモデルが記載されていない場合は、ベータに参加してお知らせください。リクエストされたモデルが優先されます。",
