          nl: "Apple Health is het meest complete systeem om gezondheidsgegevens op de iPhone te verzamelen. Het bekende probleem: de gegevens blijven in de app, zonder een eigen webdashboard. Je kunt een handmatige XML-export maken, maar dat is een technisch bestand dat tools nodig heeft om te lezen, en je moet het elke keer opnieuw doen. FitMesh iOS gaat dit veranderen.",
          ja: "Apple Health は iPhone で健康データを収集する最も包括的なシステムです。長年の問題は、データがアプリ内にとどまり、専用のウェブダッシュボードがないことです。手動で XML エクスポートはできますが、読み取るのにツールが必要な技術的なファイルで、毎回やり直す必要があります。FitMesh iOS はこれを変えます。",
          ko: "Apple Health는 iPhone에서 건강 데이터를 수집하는 가장 포괄적인 시스템입니다. 오래된 문제는 데이터가 앱 안에만 머물고 전용 웹 대시보드가 없다는 점입니다. 수동으로 XML을 내보낼 수는 있지만, 읽으려면 도구가 필요한 기술 파일이며 매번 다시 해야 합니다. FitMesh iOS가 이를 바꿀 것입니다.",
