          it: "Health Connect è l'hub centrale che Android usa per raccogliere i dati di salute da app e dispositivi indossabili: passi, battito cardiaco, sonno, allenamenti e altro. Ma è un database locale: vive sul tuo telefono, non nel cloud.",
          en: "Health Connect is the central hub that Android uses to collect health data from apps and wearables: steps, heart rate, sleep, workouts and more. But it is a local database: it lives on your phone, not in the cloud.",
