          de: "Health Connect ist der zentrale Hub, den Android für die Sammlung von Gesundheitsdaten aus Apps und Wearables verwendet: Schritte, Herzfrequenz, Schlaf, Sportaktivitäten und mehr. Es handelt sich jedoch um eine lokale Datenbank: Sie lebt auf Ihrem Telefon, nicht im Cloud-Speicher.",
          pt: "O Health Connect é o hub central que o Android usa para coletar dados de saúde de apps e wearables: passos, frequência cardíaca, sono, treinos e mais. No entanto, trata-se de uma base de dados local: vive no seu telefone, não na nuvem.",
          fr: "Health Connect est le hub central que Android utilise pour collecter des données de santé provenant d'applications et de wearables: pas, fréquence cardiaque, sommeil, entraînements et plus encore. Cependant, il s'agit d'une base de données locale: elle vit sur votre téléphone, pas dans le cloud.",
          pl: "Health Connect to centralny hub, który Android używa do zbierania danych zdrowotnych z aplikacji i wearables: kroki, tętno, sen, treningi i inne. Jest to jednak lokalna baza danych: istnieje na twoim telefonie, a nie w chmurze.",
