          nl: "Health Connect is de centrale hub die Android gebruikt om gegevens van gezondheid te verzamelen uit apps en wearables: stappen, hartslag, slaap, trainingen en meer. Het is echter een lokale database: het leeft op je telefoon, niet in de cloud.",
          ja: "Health Connectは、Androidがアプリやウェアラブルデバイスから歩数、心拍数、睡眠、ワークアウトなどの健康データを収集するための中央ハブです。ただし、これはローカルデータベースであり、クラウドではなくあなたのスマートフォン内に保存されています。",
