          pl: "Nie. Health Connect przechowuje dane fitness i zdrowia lokalnie na Twoim telefonie. Nie ma wbudowanego panelu internetowego ani kopii zapasowej w chmurze. FitMesh Sync jest brakującą warstwą, która odzwierciedla Twoje dane z Health Connect do osobistego konta w chmurze.",
          tr: "Hayır. Health Connect, cihazınızdaki yerel depolamada fitnes ve sağlık verilerini saklıyor. Bulut paneli veya yedekleme yok. FitMesh Sync, Health Connect verilerinizin bir kişisel bulut hesabına yansımasını sağlayan eksik katman.",
          nl: "Nee. Health Connect slaat fitnes- en gezondheidsdata lokaal op in uw telefoon. Er is geen ingebouwde web-dashboard of cloud-back-up. FitMesh Sync is het ontbrekende deel dat uw Health Connect-data spiegelt naar een persoonlijk cloudaccount.",
