          it: "Google Fit era un dashboard che raccolse anche i dati dai sensori di Google e da alcuni dispositivi partner. FitMesh è un dashboard di sola lettura: legge i dati dal Health Connect (dove vivono già tutti i tuoi dati dei dispositivi) e li visualizza in una singola vista. Non c'è raccolta di nuovi dati, nessun blocco.",
