          es: "Google Fit era un panel que también recogía datos de los sensores propios de Google y algunos dispositivos asociados. FitMesh es un panel de solo lectura: lee desde Health Connect (donde ya viven todos tus datos de dispositivo) e ilustra estos en una sola vista. No se recogen nuevos datos, no hay lock-in.",
          de: "Google Fit war ein Dashboard, das auch Daten von Googles eigenen Sensoren und einigen Partnergeräten sammelte. FitMesh ist ein lesendes Dashboard: Es liest aus Health Connect (wohin all Ihre Gerätedaten bereits leben) und zeigt sie in einem Überblick an. Keine neue Datensammlung, keine Lock-In-Situation.",
