          tr: "Google Fit, bir panoldu ve aynı zamanda Google'nun kendi sensörlerinden ve bazı ortak cihazlardan veri toplamaktaydı. FitMesh ise okuma sadece bir panoldur: tüm cihaz verilerinüzün (verdiğinizde) zaten Health Connect'te saklandığından, bu verileri tek bir görünümde gösterir. Yeni veri toplanmaz, kilitlenme yok.",
