      pl: "Sync Colmi Ring data on Android without the Da Fit companion app. FitMesh connects directly via Bluetooth and shows steps, sleep stages, HRV, and SpO2 in one unified dashboard.",
      tr: "Colmi Cengesi verilerini Da Fit eşlemesi uygulaması olmadan Android'da senkronize edin. FitMeshBluetooth üzerinden doğrudan bağlanarak adımlar, uyku aşamaları, HRV ve SpO2'yi tek bir birleştirilmiş panodada gösterir.",
      nl: "Synchronise Colmi Ring gegevens op Android zonder de Da Fit begeleidende app. FitMesh verbindt direct via Bluetooth en toont stappen, slapenfases, HRV, en SpO2 in één geïntegreerde dashboard.",
      ja: "Colmi RingデータをAndroidでDa Fitコンパニオンアプリなしで同期します。FitMeshはBluetooth経由で直接接続し、ステップ数、睡眠段階、HRV、SpO2を1つの統合ダッシュボードに表示します。",
      ko: "Colmi Ring 데이터를 Da Fit 콜라보 앱 없이 안드로이드에서 동기화합니다. FitMesh는 블루투스를 통해 Colmi R02, R03 및 호환 가능한 링에 직접 연결하여 단일 통합 대시보드에서 걸음 수, 수면 단계, 심박수, SpO2 및 HRV를 자동으로 표시합니다.",
